  "sdm/booking.py": "from dataclasses import dataclass, replace\nfrom typing import Optional\n\n\n@dataclass\nclass Seat:\n    seat_id: str\n    is_reserved: bool = False\n    buyer: Optional[str] = None\n\n\nclass SeatDatabase:\n    \"\"\"A stand-in for a real database: reads return a copy, like a row fetched over the network.\"\"\"\n\n    def __init__(self, *seat_ids: str):\n        self.rows = {sid: Seat(sid) for sid in seat_ids}\n\n    def get_seat(self, seat_id: str) -> Seat:\n        return replace(self.rows[seat_id])\n\n    def save(self, seat: Seat) -> None:\n        self.rows[seat.seat_id] = replace(seat)\n\n\ndef reserve(db: SeatDatabase, seat_id: str, buyer: str) -> str:\n    seat = db.get_seat(seat_id)\n    if seat.is_reserved:\n        return \"Sold out\"\n    seat.is_reserved = True\n    seat.buyer = buyer\n    db.save(seat)\n    return \"Confirmed\"\n",
  "sdm/counter.py": "import threading\n\n\nclass UnsafeCounter:\n    def __init__(self):\n        self.value = 0\n\n    def increment(self):\n        current = self.value      # 1. read\n        current = current + 1     # 2. add\n        self.value = current      # 3. write\n\n\nclass SafeCounter:\n    def __init__(self):\n        self.value = 0\n        self.lock = threading.Lock()\n\n    def increment(self):\n        with self.lock:           # only one thread at a time runs the block\n            self.value = self.value + 1\n\n\ndef interleaved_lost_update() -> int:\n    \"\"\"Replay the bad interleaving step by step: both threads read 0 before either writes.\"\"\"\n    c = UnsafeCounter()\n    a_read = c.value          # thread A reads 0\n    b_read = c.value          # thread B reads 0\n    c.value = a_read + 1      # A writes 1\n    c.value = b_read + 1      # B writes 1 — A's increment is lost\n    return c.value\n",
  "sdm/lru_cache.py": "from typing import Optional\n\n\nclass Node:\n    \"\"\"One entry in the recency list.\"\"\"\n\n    def __init__(self, key: str, value: str):\n        self.key = key\n        self.value = value\n        self.prev: Optional[\"Node\"] = None\n        self.next: Optional[\"Node\"] = None\n\n\nclass LRUCache:\n    \"\"\"Keeps at most `capacity` entries and forgets the least recently used one.\"\"\"\n\n    def __init__(self, capacity: int):\n        if capacity < 1:\n            raise ValueError(\"capacity must be at least 1\")\n        self.capacity = capacity\n        self.index: dict[str, Node] = {}   # key -> node, for O(1) lookup\n        self.head: Optional[Node] = None   # most recently used\n        self.tail: Optional[Node] = None   # least recently used\n\n    def get(self, key: str) -> Optional[str]:\n        node = self.index.get(key)\n        if node is None:\n            return None\n        self._unlink(node)\n        self._push_front(node)\n        return node.value\n\n    def put(self, key: str, value: str) -> None:\n        node = self.index.get(key)\n        if node is not None:\n            node.value = value\n            self._unlink(node)\n            self._push_front(node)\n            return\n        if len(self.index) == self.capacity:\n            lru = self.tail\n            self._unlink(lru)\n            del self.index[lru.key]\n        node = Node(key, value)\n        self.index[key] = node\n        self._push_front(node)\n\n    def keys_by_recency(self) -> list[str]:\n        \"\"\"Most recent first. Handy in tests.\"\"\"\n        out, node = [], self.head\n        while node is not None:\n            out.append(node.key)\n            node = node.next\n        return out\n\n    def _unlink(self, node: Node) -> None:\n        if node.prev is not None:\n            node.prev.next = node.next\n        else:\n            self.head = node.next\n        if node.next is not None:\n            node.next.prev = node.prev\n        else:\n            self.tail = node.prev\n        node.prev = node.next = None\n\n    def _push_front(self, node: Node) -> None:\n        node.next = self.head\n        if self.head is not None:\n            self.head.prev = node\n        self.head = node\n        if self.tail is None:\n            self.tail = node\n",
